const sheetId = 957714022;
const headers = ['ID do lead','Google Place ID','Empresa','Endereço','Site','Telefone','Categorias no Google','Nota no Google','Avaliações no Google','Situação no Google','Encontrado em','Aderência','Complexidade','Facilidade de contato','Prioridade','Motivo da prioridade','Etapa','Próxima verificação','Responsável','Revisado em','Decisor','Canal de contato','Destino do contato','Primeiro contato em','Próximo retorno','Resultado comercial','Não contatar','Motivo da perda','Busca de origem','Cidade','Segmento','ID da empresa','Situação do diagnóstico','Formulário do diagnóstico','Mensagem do convite','Enviar convite','Convite enviado em','Última resposta em','Quem respondeu','Quem falta responder','Sessões recebidas','Respostas válidas','Índice PRUMO','Resultado por área','Lacunas observadas','Briefing interno','Próxima ação','Diagnóstico concluído em','Atualizado em','Erro técnico'];
const notes = {
  2: 'Empresa descoberta pelo Lead Scout.',
  14: 'Pontuação de triagem por sinais públicos. Não é diagnóstico.',
  16: 'Mude para “Contato aceito” somente após a empresa aceitar o diagnóstico.',
  17: 'O próximo passo humano recomendado para este lead.',
  31: 'Identificador imutável que conecta lead, formulário e diagnóstico. Não edite.',
  32: 'Estado atual das respostas do diagnóstico.',
  35: 'Link de ação pronto para abrir o canal de envio.',
  42: 'Índice calculado apenas quando as cinco perspectivas estiverem completas.',
  45: 'Leitura interna produzida pelo fluxo de diagnóstico.',
  46: 'Ação recomendada para movimentar o lead.',
  49: 'Detalhe técnico para correção; fica oculto no uso diário.'
};
const color = (red, green, blue) => ({ red, green, blue });
const white = color(1, 1, 1);
const headerFormat = backgroundColor => ({ backgroundColor, textFormat: { foregroundColor: white, bold: true, fontFamily: 'Arial', fontSize: 10 }, horizontalAlignment: 'CENTER', verticalAlignment: 'MIDDLE', wrapStrategy: 'WRAP' });
const range = (startColumnIndex, endColumnIndex, startRowIndex = 0, endRowIndex = 1000) => ({ sheetId, startColumnIndex, endColumnIndex, startRowIndex, endRowIndex });
const requests = [
  { updateCells: { range: range(0, 50, 0, 1), rows: [{ values: headers.map((header, index) => ({ userEnteredValue: { stringValue: header }, ...(notes[index] ? { note: notes[index] } : {}) })) }], fields: 'userEnteredValue,note' } },
  { repeatCell: { range: range(0, 2, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.25, 0.29, 0.31)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(2, 11, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.08, 0.25, 0.21)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(11, 18, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.43, 0.27, 0.06)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(18, 31, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.12, 0.27, 0.42)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(31, 50, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.32, 0.17, 0.38)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(0, 50, 1, 1000), cell: { userEnteredFormat: { textFormat: { fontFamily: 'Arial', fontSize: 10, foregroundColor: color(0.12, 0.14, 0.15) }, verticalAlignment: 'MIDDLE', wrapStrategy: 'CLIP' } }, fields: 'userEnteredFormat.textFormat,userEnteredFormat.verticalAlignment,userEnteredFormat.wrapStrategy' } },
  { updateSheetProperties: { properties: { sheetId, gridProperties: { frozenRowCount: 1, frozenColumnCount: 3 } }, fields: 'gridProperties.frozenRowCount,gridProperties.frozenColumnCount' } },
  { updateDimensionProperties: { range: { sheetId, dimension: 'ROWS', startIndex: 0, endIndex: 1 }, properties: { pixelSize: 48 }, fields: 'pixelSize' } },
  { updateDimensionProperties: { range: { sheetId, dimension: 'ROWS', startIndex: 1, endIndex: 1000 }, properties: { pixelSize: 34 }, fields: 'pixelSize' } },
  { autoResizeDimensions: { dimensions: { sheetId, dimension: 'COLUMNS', startIndex: 0, endIndex: 50 } } },
  { setDataValidation: { range: range(16, 17, 1, 1000), rule: { condition: { type: 'ONE_OF_LIST', values: ['Revisar','Contato aceito','Convite pronto','Diagnóstico em andamento','Diagnóstico para revisar','Concluído','Fora do perfil','Erro na descoberta'].map(userEnteredValue => ({ userEnteredValue })) }, strict: true, showCustomUi: true } } },
  { setDataValidation: { range: range(32, 33, 1, 1000), rule: { condition: { type: 'ONE_OF_LIST', values: ['Não iniciado','Convite pronto','Convite enviado','Aguardando respostas','Revisão necessária','Concluído'].map(userEnteredValue => ({ userEnteredValue })) }, strict: true, showCustomUi: true } } },
  { setBasicFilter: { filter: { range: range(0, 50, 0, 1000) } } },
  { findReplace: { range: range(16, 17, 1, 1000), find: 'REVIEW', replacement: 'Revisar', matchCase: true } },
  { findReplace: { range: range(16, 17, 1, 1000), find: 'CONTACT_ACCEPTED', replacement: 'Contato aceito', matchCase: true } },
  { findReplace: { range: range(16, 17, 1, 1000), find: 'DIAGNOSTIC_INVITE_READY', replacement: 'Convite pronto', matchCase: true } },
  { findReplace: { range: range(16, 17, 1, 1000), find: 'DIAGNOSTIC_IN_PROGRESS', replacement: 'Diagnóstico em andamento', matchCase: true } },
  { findReplace: { range: range(16, 17, 1, 1000), find: 'DIAGNOSTIC_REVIEW', replacement: 'Diagnóstico para revisar', matchCase: true } },
  { findReplace: { range: range(32, 33, 1, 1000), find: 'INVITE_READY', replacement: 'Convite pronto', matchCase: true } },
  { findReplace: { range: range(32, 33, 1, 1000), find: 'INVITED', replacement: 'Convite enviado', matchCase: true } },
  { findReplace: { range: range(32, 33, 1, 1000), find: 'WAITING_FOR_SESSIONS', replacement: 'Aguardando respostas', matchCase: true } },
  { findReplace: { range: range(32, 33, 1, 1000), find: 'REVIEW_REQUIRED', replacement: 'Revisão necessária', matchCase: true } }
];
const widths = [[2,3,240],[3,4,320],[4,6,160],[7,9,100],[10,11,150],[11,15,105],[15,16,320],[16,17,190],[17,18,320],[18,23,155],[23,25,150],[25,28,180],[29,31,145],[32,33,200],[33,34,240],[34,35,360],[35,36,180],[36,40,170],[40,43,115],[45,46,440],[46,47,320],[47,49,170]];
for (const [startIndex, endIndex, pixelSize] of widths) requests.push({ updateDimensionProperties: { range: { sheetId, dimension: 'COLUMNS', startIndex, endIndex }, properties: { pixelSize }, fields: 'pixelSize' } });
for (const [startIndex, endIndex] of [[0,2],[6,7],[9,10],[28,29],[31,32],[43,45],[49,50]]) requests.push({ updateDimensionProperties: { range: { sheetId, dimension: 'COLUMNS', startIndex, endIndex }, properties: { hiddenByUser: true }, fields: 'hiddenByUser' } });
for (const [startColumnIndex, endColumnIndex] of [[2,6],[15,18],[18,28],[32,40],[45,47]]) requests.push({ repeatCell: { range: range(startColumnIndex, endColumnIndex, 1, 1000), cell: { userEnteredFormat: { wrapStrategy: 'WRAP' } }, fields: 'userEnteredFormat.wrapStrategy' } });
return [{ json: { requests } }];
